# Generated by hand on 2026-10-09: the lines_stale flag becomes two dates.

from datetime import timedelta

from django.db import migrations, models


def date_the_lines(apps, schema_editor):
    """What the flag said, as dates: a waiting entry's lines have no model
    date; any other entry's lines are dated just after its text."""
    for name in ("Setting", "Character", "CharacterVariant"):
        model = apps.get_model("core", name)
        for row in model.objects.all():
            row.text_edited_at = row.updated_at
            row.lines_ai_at = None if row.lines_stale else row.updated_at + timedelta(seconds=1)
            row.save(update_fields=["text_edited_at", "lines_ai_at"])


